-- =====================================================================================
--  Malica Office — Paramètres fiscaux tunisiens, état constaté dans les éditions 2026
--
--  RÈGLE FONDATRICE : aucun montant sans citation.
--  Chaque ligne porte son corpus, son article et un extrait littéral. Un paramètre sans
--  article ne peut pas être en confiance 'confirme'.
--
--  ÉCHELLE — le piège que ce fichier neutralise.
--  Les textes fiscaux tunisiens mélangent trois écritures d'un même nombre :
--     « 19 % »        -> ratio 0.19
--     « 0,2 % du CA » -> ratio 0.002   (et non 0.2 : erreur d'un facteur 100)
--     « 1,000 dinar » -> 1 dinar       (la virgule est décimale, le dinar a 3 décimales)
--  Toute valeur est donc stockée SOUS SA FORME CANONIQUE dans valeur_num, avec l'échelle
--  explicite, et la graphie d'origine conservée dans valeur_brute pour l'audit.
--  Le socle ne lit JAMAIS valeur_brute pour calculer.
--
--  VALIDITÉ TEMPORELLE — valid_from est fixé au 1er janvier 2026 parce que c'est la date
--  à laquelle ces valeurs sont CONSTATÉES dans les éditions officielles 2026. Ce n'est pas
--  une affirmation sur la date d'entrée en vigueur réelle, souvent bien antérieure.
--  Toute résolution sur une pièce antérieure à 2026 doit échouer, pas approximer.
--
--  CONFIANCE : 'confirme' (article + citation), 'a_confirmer' (source administrative ou
--  article manquant), 'non_trouve' (valeur non établie — la ligne existe pour que
--  l'absence soit visible, jamais pour être utilisée dans un calcul).
--
--  Idempotent.
-- =====================================================================================

insert into ref.fiscal_parameters
  (jurisdiction, code, libelle, forme, echelle, valeur_num, valeur_texte, valeur_brute,
   corpus, texte_source, article, citation, autorite, confiance, valid_from, valid_to)
select v.j, v.code, v.libelle, v.forme, v.echelle, v.num, v.txt, v.brute,
       v.corpus, v.texte, nullif(v.article,''), nullif(v.citation,''), v.autorite, v.confiance,
       date '2026-01-01', null
