-- --- Tranches de barèmes --------------------------------------------------------------
insert into ref.fiscal_scale_brackets (parameter_code, jurisdiction, valid_from, ordre, borne_min, borne_max, taux)
select v.code, 'TN', date '2026-01-01', v.ordre, v.bmin, v.bmax, v.taux
from (values
  ('IRPP_BAREME',1,0.0,5000.0,0.0),
  ('IRPP_BAREME',2,5000.001,10000.0,0.15),
  ('IRPP_BAREME',3,10000.001,20000.0,0.25),
  ('IRPP_BAREME',4,20000.001,30000.0,0.3),
  ('IRPP_BAREME',5,30000.001,40000.0,0.33),
  ('IRPP_BAREME',6,40000.001,50000.0,0.36),
  ('IRPP_BAREME',7,50000.001,70000.0,0.38),
  ('IRPP_BAREME',8,70000.001,null,0.4)
) as v(code, ordre, bmin, bmax, taux)
where not exists (select 1 from ref.fiscal_scale_brackets s
  where s.parameter_code=v.code and s.jurisdiction='TN' and s.valid_from=date '2026-01-01' and s.ordre=v.ordre);
